static int actionGroup(int a){if(retiredAction(a))return -1;if((a>=1&&a<=7)||a==35||a==36||a==53||a==60||a==61||a==SHOW_MINIGESTURES_ACTION)return 0;if(a==13||(a>=30&&a<=TASK_VIEW_ACTION)||a==FIRST_DESKTOP_ACTION||a==LAST_DESKTOP_ACTION||a==TOGGLE_HIDDEN_FILES_ACTION||a==TOGGLE_ALL_HIDDEN_FILES_ACTION)return 1;if((a>=21&&a<=23)||a==KILL_APP_ACTION)return 2;if(a==0||a==20)return 3;if(a>=47&&a<=50)return 4;if(a==BROWSER_HOME_ACTION||(a>=8&&a<=16)||(a>=37&&a<=41)||(a>=55&&a<=58))return 5;if((a>=24&&a<=29)||a==59)return 6;if((a>=42&&a<=45)||a==52||a==54)return 7;if((a>=17&&a<=19)||a==51)return 8;return -1;}
